'use strict';
const C=window.JB_CONFIG;
const A=C.assets;
const KEY='jana_bazar_v13_supabase_auth_state';
let supa=null;
let supabaseAuthReady=false;
const SUPABASE_CONFIGURED=()=>Boolean(C.supabase?.url && C.supabase?.publishableKey && C.supabase.url.startsWith('http'));
async function initSupabase(){
  if(!SUPABASE_CONFIGURED()){ console.warn('Supabase Auth not configured. Add URL and publishable key in config.js.'); return; }
  if(!window.supabase?.createClient){ toast('Supabase JS library is not loaded'); return; }
  try{
    supa=window.supabase.createClient(C.supabase.url,C.supabase.publishableKey);
    const {data}=await supa.auth.getSession();
    syncSupabaseUser(data?.session?.user||null,false);
    supabaseAuthReady=true;
    supa.auth.onAuthStateChange((_event,session)=>{ syncSupabaseUser(session?.user||null,true); });
  }catch(err){ console.error(err); toast('Supabase Auth connection failed'); }
}
function syncSupabaseUser(u,rerender=true){
  if(!u){ if(db.session){db.session=null;save();if(rerender)render();} return; }
  const m=u.user_metadata||{};
  let local=db.users.find(x=>x.supabaseId===u.id||x.email===u.email);
  if(!local){
    local={id:uid('u'),supabaseId:u.id,name:m.name||u.email?.split('@')[0]||'Customer',mobile:m.mobile||'',email:(u.email||'').toLowerCase(),role:m.role||'customer',verified:!!u.email_confirmed_at,emailVerified:!!u.email_confirmed_at,createdAt:u.created_at||now()};
    db.users.push(local);
  }else{
    local.supabaseId=u.id; local.email=(u.email||local.email||'').toLowerCase(); local.emailVerified=!!u.email_confirmed_at; local.verified=!!u.email_confirmed_at;
    if(m.name) local.name=m.name; if(m.mobile) local.mobile=m.mobile; if(m.role) local.role=m.role;
  }
  db.session=local.id; save(); if(rerender) render();
}
