function load(){try{const x=JSON.parse(localStorage.getItem(KEY));if(!x)return fresh();if(x.version===13)return x;const y=fresh();Object.assign(y,x);y.version=13;y.settings={...y.settings,...(x.settings||{})};y.locationData={...y.locationData,...(x.locationData||{})};return y}catch{return fresh()}}
