function render(){const r=route();let c='';if(r==='home')c=home();else if(r==='search')c=renderSearchPage();else if(r.startsWith('product/'))c=product(r.split('/')[1]);else if(r==='cart')c=cartPage();else if(r==='checkout')c=checkout();else if(r==='orders')c=orders();else if(r.startsWith('order/'))c=orderDetail(r.split('/')[1]);else if(r==='wishlist')c=wishlist();else if(r==='account')c=account();else if(r==='seller')c=sellerRegister();else if(r==='seller-dashboard')c=sellerDashboard();else if(r==='b2b')c=b2bPage();else if(r==='services')c=servicesPage();else if(r.startsWith('service/'))c=serviceDetail(r.split('/')[1]);else if(r==='utilities')c=utilitiesPage();else if(r==='wallet')c=walletPage();else if(r==='advertising')c=advertisingPage();else if(r==='support')c=supportPage();else if(r==='policies')c=policiesPage();else if(r==='admin')c=adminPage();else if(r.startsWith('admin/'))c=adminPage(r.split('/')[1]);else if(r==='service-provider')c=serviceProvider();else if(r==='delivery')c=deliveryPage();else c=home();$('#app').innerHTML=shell(c);}

